function main(): void {
  console.log(Intl.NumberFormat.supportedLocalesOf(["en-US", "xx", "de"]));
  console.log(Intl.getCanonicalLocales("EN-us"), Intl.getCanonicalLocales(["en-US", "en-us"]));
  const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });
  console.log(rtf.format(-1, "day"), rtf.format(2, "week"));
  console.log(rtf.formatToParts(-5, "second").map((p) => p.type + ":" + p.value + ":" + p.unit).join("|"));
  console.log(rtf.formatToParts(1, "day").map((p) => p.type + ":" + p.value).join("|"));
}
